/* Coach adaptive plan v2: evidence-gated, read-only proposals.
 * A plan is always the exact resolved user schedule, never an autogenerated preset.
 * Recommendations cannot mutate sessions or be applied without user action.
 */
(function(root,factory){const api=factory();
 if(typeof module==='object'&&module.exports)module.exports=api;
 else root.MLCCoachAdaptive=api;
})(typeof globalThis!=='undefined'?globalThis:this,function(){
 'use strict';
 function compile({today=null,checkin=null,weekly=null,memories={},declines={}}={}){
  const isScheduled=today?.status==='scheduled'&&Array.isArray(today.items)&&today.items.length>0;
  if(!isScheduled)return Object.freeze({status:'rest',priority:'schedule',items:Object.freeze([]),note:'Rest or unassigned day preserved. No substitute workout proposed.'});
  const load=checkin?.load||'unknown',items=[];
  for(const ex of today.items){
   if(!ex||typeof ex.id!=='string'||!ex.id||ex.status==='unavailable'){
    items.push(Object.freeze({exerciseId:ex?.id||null,status:'verify-exercise',weight:null,
     reason:'Exercise unavailable in the resolved custom plan. Verify the ID; Coach will not substitute exercises.',requiresApproval:true}));continue;
   }
   const memory=memories&&Object.prototype.hasOwnProperty.call(memories,ex.id)?memories[ex.id]:null;
   const caution=load==='conservative'||(memory?.signal==='review'||memory?.signal==='unavailable')||declines?.[ex.id]?.status==='review-decline';
   let status='learning',weight=null,reason='At least two qualifying completed sessions are required before a specific weight is proposed.';
   if(ex.status==='ready'&&Number.isFinite(ex.weight)&&ex.weight>0&&ex.weight<=1500){
    status=ex.action==='increase'?'increase':ex.action==='reduce'?'reduce':'hold';
    weight=ex.weight;reason=String(ex.reason||'Qualified working-set history');
    if(caution&&status==='increase'){
     status='review-increase';weight=null;
     reason=load==='conservative'?'This week’s self-reported recovery or difficulty calls for caution.':memory?.signal==='review'?'Several later outcomes for this exercise were rated worse; review before increasing.':memory?.signal==='unavailable'?'Saved outcome history needs recovery before an increase can be recommended.':'Repeated declining repetitions at comparable loads need a review before increasing.';
    }
   }
   items.push(Object.freeze({exerciseId:ex.id,name:ex.name||ex.id,status,weight,reason,
    source:ex.source||null,requiresApproval:true,personalTarget:ex.personalTarget??null}));
  }
  const priority=items.some(x=>x.status==='review-increase')?'caution':
   items.some(x=>x.status==='verify-exercise')?'verify':
   items.some(x=>x.status==='increase'||x.status==='reduce')?'progression':'monitor';
  const constrained=weekly?.daysAvailable!=null&&weekly.remaining===0;
  return Object.freeze({status:'scheduled',priority,items:Object.freeze(items),
   note:(constrained?'Reported available training days met. ':'')+
    'All changes require the user to act; custom workout and rest-day assignments remain authoritative.'});
 }
 return Object.freeze({compile});
});
